                f"Unknown output image format '{output_format}'"
            )
def hash_filelike(filelike):
    """
    Compute the hash of a file-like object, without loading it all into memory.
    """
    file_pos = 0
    if hasattr(filelike, "tell"):
        file_pos = filelike.tell()
    try:
        filelike.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass
    hasher = sha1()
    while True:
        data = filelike.read(HASH_READ_SIZE)
        if not data:
            break
        hasher.update(force_bytes(data))
    if hasattr(filelike, "seek"):
        filelike.seek(file_pos)
    return hasher.hexdigest()

def is_local_uri(uri):
    """Returns true if this is a local file path (/foo or file:/foo)."""
    if uri == "databricks":
        return False
    if is_windows() and uri.startswith("\\\\"):
        return False
    parsed_uri = urllib.parse.urlparse(uri)
    if parsed_uri.hostname and not (
        parsed_uri.hostname == "."
        or parsed_uri.hostname.startswith("localhost")
        or parsed_uri.hostname.startswith("127.0.0.1")
    ):
        return False
    scheme = parsed_uri.scheme
    if scheme == "" or scheme == "file":
        return True
    if is_windows() and len(scheme) == 1 and scheme.lower() == pathlib.Path(uri).drive.lower()[0]:
        return True
    return False
