    def __handle_recv(self, sock, read_buffers):
        if self.sock_type(sock) == socket.SOCK_DGRAM:
            reply = sock.recv(1048576)
            reply = struct.pack("!I", len(reply)) + reply
            return reply
        else:
            buf = read_buffers.get(sock)
            part = sock.recv(1048576)
            if buf is None:
