    def handle(self, *args, **options):
        email = options['email']
        try:
            profile = UserProfile.objects.get(email=email)
        except ValidationError:
            raise CommandError("No such user.")
        if options['grant']:
            if profile.has_perm(options['permission'], profile.realm):
