    def partition_disk_handler(self, disk, spec, *, partition=None, gap=None):
        log.debug("partition_disk_handler: %s %s %s %s", disk, spec, partition, gap)
        if partition is not None:
            if "size" in spec and spec["size"] != partition.size:
                trailing, gap_size = gaps.movable_trailing_partitions_and_gap_size(
                    partition
                )
                new_size = align_up(spec["size"])
                size_change = new_size - partition.size
                if size_change > gap_size:
                    raise Exception("partition size too large")
                if not self.can_resize_partition(partition):
                    raise Exception("partition cannot support resize")
                partition.size = new_size
                partition.resize = True
                for part in trailing:
                    part.offset += size_change
            self.delete_filesystem(partition.fs())
            self.create_filesystem(partition, spec)
            return
        if len(disk.partitions()) == 0:
            if disk.type == "disk":
                disk.preserve = False
                disk.wipe = "superblock-recursive"
            elif disk.type == "raid":
                disk.wipe = "superblock-recursive"
        needs_boot = self.model.needs_bootloader_partition()
        log.debug("model needs a bootloader partition? {}".format(needs_boot))
        can_be_boot = boot.can_be_boot_device(disk)
        if needs_boot and len(disk.partitions()) == 0 and can_be_boot:
            self.add_boot_disk(disk)
            gap = gaps.largest_gap(disk)
            if spec["size"] > gap.size:
                log.debug(
                    "Adjusting request down from %s to %s", spec["size"], gap.size
                )
                spec["size"] = gap.size
        gap = gap.split(spec["size"])[0]
        self.create_partition(disk, gap, spec)
        log.debug("Successfully added partition")
    async def copy_logs_to_target(self, context):
        if self.opts.dry_run and "copy-logs-fail" in self.app.debug_flags:
            raise PermissionError()
        if self.app.controllers.Filesystem.reset_partition_only:
            return
        if self.app.base_model.source.current.variant == "core":
            return
        target_logs = os.path.join(self.app.base_model.target, "var/log/installer")
        if self.opts.dry_run:
            os.makedirs(target_logs, exist_ok=True)
        else:
            await self.copy_cloud_init_logs(target_logs)
            await self.app.command_runner.run(
                ["cp", "-aT", "/var/log/installer", target_logs]
            )
            set_log_perms(target_logs, group_write=False)
        journal_txt = os.path.join(target_logs, "installer-journal.txt")
        try:
            with open_perms(journal_txt) as output:
                await self.app.command_runner.run(
                    ["journalctl", "-b"],
                    capture=True,
                    stdout=output,
                    stderr=subprocess.STDOUT,
                )
        except Exception:
            log.exception("saving journal failed")
def align_up(size, block_size=1 << 20):
    return (size + block_size - 1) & ~(block_size - 1)
def open_perms(filename, **kwargs):
    tf = None
    try:
        dirname = os.path.dirname(filename)
        os.makedirs(dirname, exist_ok=True)
        tf = tempfile.NamedTemporaryFile(dir=dirname, delete=False, mode="w")
        yield tf
        tf.close()
        set_log_perms(tf.name, **kwargs)
        os.rename(tf.name, filename)
    except OSError as e:
        if tf is not None:
            os.unlink(tf.name)
        raise e
def write_file(filename, content, **kwargs):
    with open_perms(filename, **kwargs) as tf:
        tf.write(content)

