        "-dSAFER",
        "-sDEVICE=ppmraw",
        f"-sOutputFile={outfile}",
        "-c",
        f"{-bbox[0]} {-bbox[1]} translate",
        "-f",
        infile,
        "-c",
        "showpage",
    ]
    if gs_windows_binary is not None:
        if not gs_windows_binary:
            raise OSError("Unable to locate Ghostscript on paths")
        command[0] = gs_windows_binary
