def _command_output(
    command: list[str], env: typing.Optional[dict[str, str]] = None
) -> str:
    """Run command and capture its output.
    Try to execute given command (argv list) and return its stdout, or return
    a textual error if it failed.
    """
    try:
        sp = subprocess.run(
            command,
            check=False,
            encoding="UTF-8",
            env=env,
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            timeout=1800,
        )
    except subprocess.TimeoutExpired as error:
        raise OSError(
            f"Error: command {str(error.cmd)} timed out"
            f" after {error.timeout} seconds: {error.stdout.rstrip()}"
        ) from error
    if sp.returncode == 0:
        return sp.stdout.rstrip()
    raise OSError(
        "Error: command %s failed with exit code %i: %s"
        % (str(command), sp.returncode, sp.stdout.rstrip())
    )

